36			}
37			var st txsaga.ExecutionState
38			if err := json.Unmarshal(pe.State, &st); err != nil {
39				return nil, fmt.Errorf("execution %q state: %v: %w", id, err, ErrCorruptStore)
40			}
41			if len(pe.Payload) > 0 {
42				var p any
43				if err := json.Unmarshal(pe.Payload, &p); err != nil {
44					return nil, fmt.Errorf("execution %q payload: %v: %w", id, err, ErrCorruptStore)
45				}
46				st.Payload = p
47			}
48			if st.BusinessKey != business || st.IdempotencyKey != idem {
49				return nil, fmt.Errorf("execution %q identity mismatch (got %q/%q): %w",
50					id, st.BusinessKey, st.IdempotencyKey, ErrCorruptStore)
51			}
52			if st.Steps == nil {
53				// 归一化：createExecution 总是写入非 nil 的步骤切片。
54				st.Steps = []txsaga.StepState{}
55			}
56			d.execs[id] = &st
57		}
58	
59		// 定义绑定：业务键必须与某个执行一致，名称/指纹必须匹配。
60		for business, b := range ps.Bindings {
61			if b.SagaName == "" || b.Fingerprint == "" {
62				return nil, fmt.Errorf("binding for %q is incomplete: %w", business, ErrCorruptStore)
63			}
64			matched := false
65			for id, st := range d.execs {
66				bk, _, _ := splitExecID(id)
67				if bk == business {
68					if st.SagaName != b.SagaName || st.Fingerprint != b.Fingerprint {
69						return nil, fmt.Errorf("binding for %q disagrees with execution %q: %w",
70							business, id, ErrCorruptStore)
71					}
