171		idx := strings.IndexByte(id, 0)
172		if idx <= 0 || idx == len(id)-1 {
173			return "", "", false
174		}
175		return id[:idx], id[idx+1:], true
176	}
177	
178	// parseEventID 解析根包分配的 evt-%020d 事件编号，用于顺序与序号校验。
